{"command":"python3 -c "
import json
d = json.load(open('/tmp/npm-audit-output.json'))
vulns = d['vulnerabilities']

def collect_advisories(name, seen_pkgs=None, seen_adv=None):
    if seen_pkgs is None: seen_pkgs=set()
    if seen_adv is None: seen_adv=set()
    if name in seen_pkgs or name not in vulns:
        return seen_adv
    seen_pkgs.add(name)
    info = vulns[name]
    for v in info.get('via', []):
        if isinstance(v, dict):
            seen_adv.add(v.get('url') or v.get('title'))
        else:
            collect_advisories(v, seen_pkgs, seen_adv)
    return seen_adv

prod_direct = ['body-parser','csurf','express','express-session','forever','helmet','marked','mongodb','swig','underscore']
for name in prod_direct:
    adv = collect_advisories(name)
    print(name, '-> total distinct advisories in subtree:', len(adv))
    for a in sorted(adv):
        print('   ', a)
"
","description":"Compute total distinct advisories per direct dependency subtree"}

